import axios from 'axios';
import { writeFileSync } from 'fs';
import os from 'os';
import path from 'path';
import logout from '../commands/logout';
import { User } from '../types';
import { MKDB_BASE_URL } from './env.util';
import { readFileSafely } from './files.util';
import logger from './logger.util';

const configPath = path.join(os.homedir(), '.mkdb.json');

export const getGlobalCliConfig = (): null | { user: User } => {
  const data = readFileSafely(configPath);
  return data ? JSON.parse(data) : null;
};

export const getLoggedInUser = () => {
  const config = getGlobalCliConfig();
  return config?.user as User | undefined;
};

export const writeGlobalCliConfig = (config: any) =>
  writeFileSync(configPath, JSON.stringify(config));

export const writeUserData = (userData?: Partial<User>) =>
  writeGlobalCliConfig({
    user: userData ? { ...getLoggedInUser(), ...userData } : undefined,
  });

export const updateUserDataAndPersist = async (data: Partial<User>) => {
  const currentUser = getLoggedInUser();
  if (!currentUser) return 500;

  const res = await axios
    .patch(`${MKDB_BASE_URL}/api/users/${currentUser.id}`, data, {
      headers: { Authorization: currentUser.apiToken },
    })
    .catch((error) => {
      logger.dev.log('error:', [
        error.response.status,
        error.response.statusText,
      ]);
      if (error.response.status === 401) {
        logger.log(
          'looks like your session has expired. please login again.\n\nmkdb login',
        );
        logout(true);
        logger.log('error', error.response.data.message);
      }

      return undefined;
    });

  if (res?.status === 200) {
    writeUserData(data);
  }

  return res?.status;
};
